CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS site_settings (id int PRIMARY KEY DEFAULT 1 CHECK(id=1), data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, title text NOT NULL, subtitle text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', cover text NOT NULL DEFAULT '', start_date date, end_date date, participant_min int DEFAULT 0, participant_max int DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','private')), private_token_hash text UNIQUE, featured boolean NOT NULL DEFAULT false, location text NOT NULL DEFAULT '', reminder text NOT NULL DEFAULT '', days jsonb NOT NULL DEFAULT '[]', destination_ids jsonb NOT NULL DEFAULT '[]', stops jsonb NOT NULL DEFAULT '[]', infos jsonb NOT NULL DEFAULT '[]', gallery jsonb NOT NULL DEFAULT '[]', published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_trips_public ON trips(status,visibility,published_at DESC);
CREATE TABLE IF NOT EXISTS destinations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, region text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Alam', description text NOT NULL DEFAULT '', tips text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', latitude double precision, longitude double precision, featured boolean DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), path text NOT NULL, alt_text text NOT NULL DEFAULT '', mime_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, admin_id uuid REFERENCES admins(id) ON DELETE SET NULL, action text NOT NULL, entity text NOT NULL, entity_id text, created_at timestamptz NOT NULL DEFAULT now());
